      if (m.color) { m.textCR=ratio(m.color,m.cardBg); m.iconCR=ratio(m.iconFill,m.cardBg); }
      rows.push({w,theme,name,...m});
      await p.screenshot({path:`${OUT}${name}-${w}-${theme}.png`,fullPage:true});
